/**
 * LQIP (Low Quality Image Placeholder) utilities
 *
 * Reads `src/assets/image-manifest.json` (generated by
 * `pnpm generate:images` → `src/scripts/generateImageManifest.ts`) and turns the
 * stored compact color strings into CSS gradients for image placeholders.
 *
 * The manifest is loaded lazily and cached per process, so after regenerating it
 * you must restart the dev server or rebuild the site to see the changes.
 */

import { getImageEntry } from '@lib/image-manifest-accessor';
import { lqipToGradient } from '@scripts/lib/lqip-color';

/** Get the LQIP gradient CSS for an image (path or remote URL), if one is recorded. */
function getLqipGradient(imagePath: string): string | undefined {
  return lqipToGradient(getImageEntry(imagePath)?.lqip);
}

/**
 * Get LQIP style for an image
 * Returns background-image style with gradient, or undefined when unavailable
 */
export function getLqipStyle(imagePath: string): string | undefined {
  const gradient = getLqipGradient(imagePath);
  return gradient ? `background-image:${gradient}` : undefined;
}

/**
 * Get LQIP props for component usage
 */
export function getLqipProps(imagePath: string): { style?: string; class?: string } {
  const style = getLqipStyle(imagePath);
  if (style) return { style };
  // No manifest entry: fall back to a neutral background.
  return { class: 'lqip-fallback' };
}
